class SyncJob:
    def __init__(self, sink, checkpoints):
        self.sink = sink
        self.checkpoints = checkpoints

    def run(self, records):
        for record_id, text in records:
            if record_id <= self.checkpoints.value:
                continue
            self.sink.write((record_id, text))
            # Commit durable output before advancing the checkpoint: the
            # checkpoint may only reference IDs already present in durable
            # output. If the checkpoint save fails after this commit, the
            # sink deduplicates by ID on flush, so replaying the record is
            # safe (no duplication, no loss).
            self.sink.flush()
            self.checkpoints.save(record_id)

